NS_IMETHODIMP ExchangeLanguageInteropFactory::CreateOAuth2Details(
    const nsACString& type, const nsACString& hostname,
    const nsACString& username, IOAuth2CustomDetails** result) {
  NS_ENSURE_ARG_POINTER(result);

  RefPtr<ExchangeOAuth2CustomDetails> details;
  nsresult rv = ExchangeOAuth2CustomDetails::ForAccount(
      type, hostname, username, getter_AddRefs(details));
  NS_ENSURE_SUCCESS(rv, rv);

  details.forget(result);

  return NS_OK;
}
